// The software is in Public Domain under http://unlicense.org, see link for details.
// The original "Memorial Church" HDR image (C) Paul Debevec,
// available at https://www.pauldebevec.com/Research/HDR/ (licensing
// status unclear).

// Hardcoded lossily compressed 128x192 version of "Memorial Church" HDR image.
// WARNING: the shader is heavy and may crash your WebGL.
// The image data is in "Common" tab.
// See bottom of this tab for the source
// of the C++ program used to produce the LUT.
// The tonemaping used in this shader is intentionally very
// simplistic per-channel Reinhard.
// Mouse click to select reference luminance.
// Hold mouse for nearest sampling.

// The many of tonemapping examples on Shadertoy are
// somewhat undermined by the lack of appropriate HDR images
// to show them off. One option is to produce a sufficiently interesting
// physically-based rendered (PBR) image (e.g. using a ray-tracer), but that
// has its own complexity.
// This shaders instead aims to provide a crudely compressed
// low-resolution version of the well-known "Memorial Church" HDR image.
// Hopefully it is still useful in this form, assuming your WebGL can
// handle the large constant array and a bit heavy shader.
// The original image is 512x768 pixels, with color values in
// [0;274] range with 1.0 being around LDR "white".
// The dynamic range is ~ 1:250000.
// The compressed image is 128x192 pixels (1/4 scale), and is basically
// an approximation of the original by a collection of 8x8 and 4x4
// solid color blocks, fit to the budget of 64 KB LUT, with 32 bits per block.
// See code for the details of the compression scheme.
// The fetch() function below acts as API to get HDR texels from
// 128x192 image.
// The jagginess in this shader is further hidden by a blurry bicubic sampling.

//==============================================================================

const int ORIG_W=512,ORIG_H=768;
const int W=128,H=192;

//==============================================================================
// Get uint from LUT.
// The LUT is stored as uvec4[], simply because WebGL implementations
// seem happier with it over simple array of uints, see e.g.
// https://www.shadertoy.com/view/MXyGW1 vs https://www.shadertoy.com/view/43y3Dt.

uint get_uint(int i)
{
    return LUT[i>>2][i&3];
}

//==============================================================================
// Decode HDR color stored as uint32.

// Format: 2:14:8:8 - index of the largest component,
// its value (logscale), ratios of the 2 remaining
// components relative to it.
// Index '3' means block needs splitting, and the remaining
// bits are simply index into the LUT of the start
// of the 4 sub-blocks.

vec3 decode(uint bits)
{
    vec3 ret=vec3(0);
    ret.r=exp2(0.001*float((bits>>16)&0x3FFFu)-9.0);
    ret.g=ret.r*float((bits>>0)&255u)/255.0;
    ret.b=ret.r*float((bits>>8)&255u)/255.0;
    if((bits>>30)==1u) ret=ret.yzx;
    if((bits>>30)==2u) ret=ret.zxy;
    return ret;
}

//==============================================================================
// Fetch a single texel.

// Block is either 8x8 (in the original image scale) solid color,
// or split into 4 4x4 sub-blocks. The split is currently not recursive
// (sub-blocks are solid color), though it can be done.

vec3 fetch(ivec2 v)
{
    if(v.x<0||v.x>=W||v.y<0||v.y>=H) return vec3(0);
    uint bits=get_uint((v.y>>1)*(W/2)+(v.x>>1));
    if((bits>>30)==3u) return decode(get_uint(int(bits&0x3FFFFFFFu)+2*(v.y&1)+(v.x&1)));
    else return decode(bits);
}

//==============================================================================
// Mitchell-Netravali bicubic filter, see e.g.
// https://www.shadertoy.com/view/Dlc3Rn.

vec3 filterBC(
    vec3 v00,vec3 v10,vec3 v20,vec3 v30,
    vec3 v01,vec3 v11,vec3 v21,vec3 v31,
    vec3 v02,vec3 v12,vec3 v22,vec3 v32,
    vec3 v03,vec3 v13,vec3 v23,vec3 v33,
    float B,float C,vec2 uv)
{
	ivec2 xy=ivec2(floor(uv));
	float x=uv.x-float(xy.x);
	float y=uv.y-float(xy.y);
	mat4 W=mat4( // WARNING: column-major.
		B/6.0      , 1.0-B/3.0   , B/6.0           , 0.0    ,
		-C-0.5*B   , 0.0         , C+0.5*B         , 0.0    ,
		2.0*C+0.5*B, C+2.0*B-3.0 , -2.0*C-2.5*B+3.0, -C     ,
		-C-B/6.0   , -C-1.5*B+2.0, C+1.5*B-2.0     , C+B/6.0);
	vec4 Wx=W*vec4(1.0,x,x*x,x*x*x);
	vec4 Wy=W*vec4(1.0,y,y*y,y*y*y);
	return
        Wx.x*Wy.x*v00+
        Wx.y*Wy.x*v10+
        Wx.z*Wy.x*v20+
        Wx.w*Wy.x*v30+
        Wx.x*Wy.y*v01+
        Wx.y*Wy.y*v11+
        Wx.z*Wy.y*v21+
        Wx.w*Wy.y*v31+
        Wx.x*Wy.z*v02+
        Wx.y*Wy.z*v12+
        Wx.z*Wy.z*v22+
        Wx.w*Wy.z*v32+
        Wx.x*Wy.w*v03+
        Wx.y*Wy.w*v13+
        Wx.z*Wy.w*v23+
        Wx.w*Wy.w*v33;
}

//==============================================================================
// Texture sampling.

vec3 tex_nearest(vec2 uv)
{
    return fetch(ivec2(uv));
}

vec3 tex_bicubic(vec2 uv)
{
    // NOTE: we go with fairly blurry B-spline here
    // to better hide artifacts.
    //     B-Spline is (1,0).
    //     "The" Mitchell-Netravali is (1/3,1/3).
    //     Catmull-Rom is (0,1/2).
    float B=1.0,C=0.0; 
    uv-=0.5;
    ivec2 ij=ivec2(floor(uv));
    uv-=vec2(ij);
    vec3 v00=fetch(ij+ivec2(-1,-1));
    vec3 v10=fetch(ij+ivec2( 0,-1));
    vec3 v20=fetch(ij+ivec2( 1,-1));
    vec3 v30=fetch(ij+ivec2( 2,-1));
    vec3 v01=fetch(ij+ivec2(-1, 0));
    vec3 v11=fetch(ij+ivec2( 0, 0));
    vec3 v21=fetch(ij+ivec2( 1, 0));
    vec3 v31=fetch(ij+ivec2( 2, 0));
    vec3 v02=fetch(ij+ivec2(-1, 1));
    vec3 v12=fetch(ij+ivec2( 0, 1));
    vec3 v22=fetch(ij+ivec2( 1, 1));
    vec3 v32=fetch(ij+ivec2( 2, 1));
    vec3 v03=fetch(ij+ivec2(-1, 2));
    vec3 v13=fetch(ij+ivec2( 0, 2));
    vec3 v23=fetch(ij+ivec2( 1, 2));
    vec3 v33=fetch(ij+ivec2( 2, 2));
    return max(vec3(0.0),filterBC(
        v00,v10,v20,v30,
        v01,v11,v21,v31,
        v02,v12,v22,v32,
        v03,v13,v23,v33,
        B,C,
        uv));
}

//==============================================================================
// Tonemapping.
// Simple per-channel Reinhard operator.

vec3 tonemap(vec3 v)
{
    return v/(1.0+v);
}

//==============================================================================
// Main image.

void mainImage(out vec4 fragColor,in vec2 fragCoord)
{
    int SCALE=ORIG_H/H;
    float ref=exp(8.0*(iMouse.x/iResolution.x-0.5)); // Reference luminance.
    if(length(iMouse.xy)<10.0) ref=1.0;
    vec2 uv=fragCoord;
    uv.y=iResolution.y-uv.y;
    uv=mod(uv/float(SCALE)+iTime,vec2(W,H));
    vec3 col=tex_nearest(uv);
    if(iMouse.z<=0.0) col=tex_bicubic(uv);
    col=max(col,0.0);
    col/=ref;
    col=tonemap(col);
    col=mix(12.92*col,1.055*pow(col,vec3(1.0/2.4))-0.055,step(0.0031308,col)); // sRGB
    fragColor=vec4(col,1.0);
}

